use crate::aap::caps::state_read;

struct Node;

fn parse(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let mut out: Vec<String> = Vec::new();
    if t.starts_with('[') {
        // JSON-array-like: collect quoted strings.
        let mut in_str = false;
        let mut cur = String::new();
        let mut esc = false;
        for c in t.chars() {
            if in_str {
                if esc {
                    cur.push(c);
                    esc = false;
                } else if c == '\\' {
                    esc = true;
                } else if c == '"' {
                    in_str = false;
                    if !cur.is_empty() {
                        out.push(core::mem::take(&mut cur));
                    }
                    cur.clear();
                } else {
                    cur.push(c);
                }
            } else if c == '"' {
                in_str = true;
            }
        }
        if !out.is_empty() {
            return out;
        }
    }
    for part in t.split(|c: char| c.is_whitespace() || c == ',' || c == '\u{1e}') {
        let p = part.trim().trim_matches('"').trim_matches('\'');
        if !p.is_empty() {
            out.push(p.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in ["urls", "subscriptions", "feeds", "subscription-list", "list"] {
            if let Some(raw) = state_read::get(key) {
                let urls = parse(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
